        synchronized (this) {
            if (amount > balance) {
                return;
            }

            try {
                Thread.sleep(100);
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
                return;
            }

            balance = balance - amount;
        }
    }

    public int getBalance() {
        return balance;
    }
